/** Plain-English takeaways generated by the API. */
import type { Insight } from "../types";

const KIND_LABEL: Record<Insight["kind"], string> = {
  bias: "Bias",
  accuracy: "Accuracy",
  risk: "Risk sizing",
  decision: "Decision timing",
  horizon: "Lead time",
  day: "Daily",
  regime: "Wind regime",
};

export function Insights({ items }: { items: Insight[] }) {
  return (
    <ul className="insights">
      {items.map((i) => (
        <li key={i.kind + i.text}>
          <span className="insight-kind">{KIND_LABEL[i.kind]}</span>
          <p>{i.text}</p>
        </li>
      ))}
    </ul>
  );
}
